import pandas as pd

from src.playcalls.unmatched import (
    CLASSIFICATIONS,
    classify_unmatched,
    coverage_summary,
)


def _unmatched(**overrides):
    row = {"play_id": 1, "st_play_type": None, "down": 1, "distance": 10}
    row.update(overrides)
    return pd.DataFrame([row])


def test_every_row_gets_a_classification():
    unmatched = pd.DataFrame([
        {"play_id": 1, "st_play_type": "kickoff_tb", "down": 0, "distance": 0},
        {"play_id": 2, "st_play_type": None, "down": 1, "distance": 10},
    ])
    result = classify_unmatched(unmatched, pd.DataFrame(), pd.DataFrame())
    assert result["classification"].isin(CLASSIFICATIONS).all()


def test_special_teams_plays_are_labelled():
    result = classify_unmatched(
        _unmatched(st_play_type="kickoff_tb"), pd.DataFrame(), pd.DataFrame()
    )
    assert result.loc[0, "classification"] == "special_teams"


def test_special_teams_wins_over_run_and_pass():
    """A two-point rush is special teams, not a scrimmage down."""
    rushing = pd.DataFrame([{"play_id": 1, "offense": "TXBA"}])
    result = classify_unmatched(
        _unmatched(st_play_type="two_point_rush"), rushing, pd.DataFrame()
    )
    assert result.loc[0, "classification"] == "special_teams"


def test_unmatched_run_is_flagged():
    rushing = pd.DataFrame([{"play_id": 99, "offense": "TXBA"}])
    result = classify_unmatched(
        _unmatched(play_id=99), rushing, pd.DataFrame()
    )
    assert result.loc[0, "classification"] == "unmatched_run"


def test_unmatched_pass_is_flagged():
    passing = pd.DataFrame([{"play_id": 99, "offense": "TXBA"}])
    result = classify_unmatched(
        _unmatched(play_id=99), pd.DataFrame(), passing
    )
    assert result.loc[0, "classification"] == "unmatched_pass"


def test_opponent_plays_are_not_counted_as_baylor_scrimmage():
    """The rushing feed carries both teams. Only TXBA rows are ours."""
    rushing = pd.DataFrame([{"play_id": 99, "offense": "ALAU"}])
    result = classify_unmatched(_unmatched(play_id=99), rushing, pd.DataFrame())
    assert result.loc[0, "classification"] == "unknown"


def test_empty_input_returns_empty_with_the_column():
    result = classify_unmatched(pd.DataFrame(), pd.DataFrame(), pd.DataFrame())
    assert "classification" in result.columns
    assert result.empty


def test_coverage_summary_reports_no_gap_when_counts_agree():
    summary = coverage_summary(829, 829, 1084, 1084)
    assert summary["run_gap"] == 0
    assert summary["missing_share"] == 0.0


def test_coverage_summary_reports_a_real_shortfall():
    """If PFF has 23 more runs than the chart, that is a charting gap."""
    summary = coverage_summary(20, 43, 59, 59)
    assert summary["run_gap"] == 23
    assert round(summary["missing_share"], 3) == round(23 / 102, 3)

