def _play_key(series: pd.Series) -> pd.Series:
    """Normalise play_id to a string that compares across sources.

    The joined table holds play_id as float64, because unmatched charting rows
    make the column nullable. A naive .astype(str) then yields "5642403.0" on
    one side and "5642403" on the other, and every merge silently matches
    nothing. Going through nullable Int64 first strips the decimal.
    """
    return (
        pd.to_numeric(series, errors="coerce").astype("Int64").astype(str)
    )


