  font-family: var(--display);
  font-weight: 700;
  font-size: 1.65rem;
  letter-spacing: -.015em;
  line-height: 1.2;
  margin: 64px 0 16px;
  text-wrap: balance;
}

h3 {
  font-family: var(--body);
  font-weight: 600;
  font-size: 1.02rem;
  letter-spacing: .01em;
  margin: 40px 0 12px;
  color: var(--accent);
}

p { margin: 0 0 18px; }

strong { font-weight: 600; }

hr {
  border: 0;
  border-top: 1px solid var(--hairline);
  margin: 56px 0 0;
}

ul { padding-left: 1.1rem; margin: 0 0 18px; }
li { margin-bottom: 10px; }
li::marker { color: var(--gold); }

code {
  font-family: var(--data);
  font-size: .86em;
  background: var(--surface);
  border: 1px solid var(--hairline);
  border-radius: 3px;
  padding: .1em .35em;
}

pre {
  background: var(--surface);
  border: 1px solid var(--hairline);
  border-left: 3px solid var(--gold);
  padding: 16px 18px;
  overflow-x: auto;
  font-size: .84rem;
}

pre code { background: none; border: 0; padding: 0; }

em { color: var(--muted); }

/* ---- tables ---- */

.tablewrap {
  overflow-x: auto;
  border: 1px solid var(--hairline);
  background: var(--surface);
  margin: 0 0 28px;
}

table {
  border-collapse: collapse;
  width: 100%;
  font-size: .82rem;
  font-variant-numeric: tabular-nums;
}

thead th {
  font-family: var(--data);
  font-size: .68rem;
  letter-spacing: .08em;
  text-transform: uppercase;
  color: var(--muted);
  font-weight: 400;
  text-align: right;
  padding: 12px 14px;
  border-bottom: 1px solid var(--ink);
  white-space: nowrap;
}

thead th:first-child, thead th:nth-child(2) { text-align: left; }

tbody td {
  padding: 9px 14px;
  border-bottom: 1px solid var(--hairline);
  text-align: right;
  white-space: nowrap;
}

tbody td:first-child, tbody td:nth-child(2) { text-align: left; }
tbody tr:last-child td { border-bottom: 0; }

/* ---- footer ---- */

.colophon {
  margin-top: 72px;
  padding-top: 24px;
  border-top: 1px solid var(--hairline);
  font-size: .8rem;
  color: var(--muted);
}

@media (prefers-reduced-motion: reduce) {
  * { animation: none !important; transition: none !important; }
}

@media (max-width: 480px) {
  .masthead { padding-block: 36px 16px; }
  .figure .value { font-size: 1.9rem; }
}
</style>
"""


def _figures() -> str:
    season = pd.read_csv("outputs/tables/by_season.csv").set_index("season")
    run_pass = pd.read_csv("outputs/tables/by_run_pass.csv")
    down = pd.read_csv("outputs/tables/by_down_distance.csv")

    def rate(df, season_year, column, key):
        row = df[(df["season"] == season_year) & (df[column] == key)]
        return row.iloc[0]["success_rate"] if not row.empty else float("nan")

    s24 = season.loc[2024, "success_rate"]
    s25 = season.loc[2025, "success_rate"]
    fd24 = rate(down, 2024, "down_distance", "1st & 10")
    fd25 = rate(down, 2025, "down_distance", "1st & 10")
    r24 = rate(run_pass, 2024, "run_pass", "R")
    r25 = rate(run_pass, 2025, "run_pass", "R")

    p24 = rate(run_pass, 2024, "run_pass", "P")
    p25 = rate(run_pass, 2025, "run_pass", "P")
    graded24 = int(season.loc[2024, "graded"])

    cards = [
        ("Success rate 2024", f"{s24 * 100:.1f}%", f"{graded24} graded plays", False),
        ("Success rate 2025", f"{s25 * 100:.1f}%",
         f"down {(s24 - s25) * 100:.1f} points", True),
        ("1st &amp; 10", f"−{(fd24 - fd25) * 100:.1f}",
         "points, the biggest move", True),
        ("Run game", f"−{(r24 - r25) * 100:.1f}",
         f"points, vs −{(p24 - p25) * 100:.1f} passing", True),
    ]

    html = ['<div class="figures">']
    for label, value, note, is_down in cards:
        cls = "figure is-down" if is_down else "figure"
        html.append(
            f'<div class="{cls}"><span class="label">{label}</span>'
            f'<span class="value">{value}</span>'
            f'<span class="note">{note}</span></div>'
        )
    html.append("</div>")
    return "".join(html)


def main() -> None:
    with open("outputs/REPORT.md", encoding="utf-8") as handle:
        text = handle.read()

    # The masthead replaces the Markdown's own title block.
    body_md = text.split("---", 1)[1] if "---" in text else text

    html_body = markdown.markdown(
        body_md, extensions=["tables", "fenced_code", "sane_lists"]
    )
    html_body = html_body.replace("<table>", '<div class="tablewrap"><table>')
    html_body = html_body.replace("</table>", "</table></div>")

    match = pd.read_csv("outputs/match_report.csv")
    games = len(match)
    plays = int(match["charted_plays"].sum())
    match_rate = match["matched"].sum() / plays

    season = pd.read_csv("outputs/tables/by_season.csv").set_index("season")
    drop = (season.loc[2024, "success_rate"] - season.loc[2025, "success_rate"]) * 100

    page = f"""{STYLE}
<div class="wrap">
  <header class="masthead">
    <p class="eyebrow">Applied Performance &middot; Self-scout</p>
    <h1>The offense lost first down</h1>
    <p class="standfirst">Baylor's offensive success rate fell eight points between
    2024 and 2025 under the same coordinator and the same quarterback. Almost all
    of it happened on first down and in the run game.</p>
  </header>

  <div class="facts">
    <span>{games} games</span>
    <span>{plays:,} charted plays</span>
    <span>2024 &ndash; 2025</span>
    <span>PFF join {match_rate:.1%}</span>
  </div>

  {_figures()}

  {html_body}

  <p class="colophon">Generated from <code>outputs/REPORT.md</code> in
  <code>PlayCalls_SuccessRate_EPA</code>. Every figure is reproducible with
  <code>run.py</code>, <code>build_tables.py</code> and <code>build_report.py</code>.
  Baylor play-call terminology &mdash; internal use only.</p>
</div>
"""

    with open("outputs/report.html", "w", encoding="utf-8") as handle:
        handle.write(page)
    print(f"wrote outputs/report.html ({len(page):,} chars)")


if __name__ == "__main__":
    main()
